parameters.jsCode:
const c = $input.first().json;
let touchpoint = null;

if (!c.check_in_1_sent && c.days_since_start >= 7) {
  touchpoint = {type: '7day', message: `Hi ${c.first_name}! Just checking in - how's your new coverage working out? Any questions? - ${process.env.AGENT_NAME}`};
} else if (!c.check_in_30_sent && c.days_since_start >= 30) {
  touchpoint = {type: '30day', message: `Hi ${c.first_name}! Your policy has been active for a month. Hope everything is great! Remember: I'm always here if you need anything. Also, know anyone who needs coverage? - ${process.env.AGENT_NAME}`};
} else if (!c.renewal_reminder_sent && c.days_until_renewal <= 30) {
  touchpoint = {type: 'renewal', message: `Hi ${c.first_name}! Your ${c.coverage_type} policy renews in ${Math.floor(c.days_until_renewal)} days. Let's review to make sure you still have the best coverage. Book a call: ${process.env.CALENDAR_BOOKING_LINK}`};
}

return {json: {...c, touchpoint}};
